#include <stdint.h>

/* Registros para el LED LD2 (PA5) */
#define RCC_AHB2ENR     (*(volatile uint32_t *)(0x40021000UL + 0x4CUL))
#define GPIOA_MODER     (*(volatile uint32_t *)(0x48000000UL + 0x00UL))
#define GPIOA_BSRR      (*(volatile uint32_t *)(0x48000000UL + 0x18UL))

/* Registros de diagnóstico del núcleo ARM Cortex-M4 (System Control Block) */
#define SCB_CFSR        (*(volatile uint32_t *)0xE000ED28UL)
#define SCB_HFSR        (*(volatile uint32_t *)0xE000ED2CUL)
#define SCB_BFAR        (*(volatile uint32_t *)0xE000ED38UL)

static void trigger_bus_fault(void)
{
    /* Zona reservada vacía entre SRAM (0x2001FFFF) y Periféricos (0x40000000) */
    volatile uint32_t *invalid_addr = (volatile uint32_t *)0x30000000UL;

    /* Lectura ilegal: dispara BusFault preciso que escala a HardFault */
    uint32_t crash_data = *invalid_addr;
    (void)crash_data;
}

int main(void)
{
    /* Encender LD2 como señal de que el programa inició bien */
    RCC_AHB2ENR |= (1UL << 0);
    GPIOA_MODER &= ~(3UL << 10);
    GPIOA_MODER |=  (1UL << 10);
    GPIOA_BSRR   =  (1UL << 5);

    /* Provocar el fallo de bus a propósito */
    trigger_bus_fault();

    /* Esta línea jamás se ejecutará: apagado de LD2 */
    GPIOA_BSRR = (1UL << 21);

    while (1) {
    }
}
